  "shared.pages_cookies.chlat_work_may_store_small_preferences_directly_in_your": "ChlatWork may store small preferences directly in your browser so the site feels consistent when you return.",
  "shared.pages_cookies.remembers_your_selected_language": "remembers your selected language.",
  "shared.pages_cookies.remembers_light_or_dark_mode": "remembers light or dark mode.",
