  "shared.pages_cookies.an_essential_http_only_login_cookie_that_expires_after": "an essential HttpOnly login cookie that expires after approximately 15 minutes.",
  "shared.pages_cookies.an_essential_http_only_session_cookie_that_expires_after": "an essential HttpOnly session cookie that expires after approximately 30 days and supports secure session renewal.",
  "shared.pages_cookies.temporary_http_only_telegram_state_and_pkce_cookies_protect": "Temporary HttpOnly Telegram state and PKCE cookies protect the login callback and expire after approximately 10 minutes.",
  "shared.pages_cookies.authentication_cookies_are_strictly_necessary_when_you_choose_to": "Authentication cookies are strictly necessary when you choose to sign in. They are not available to browser JavaScript and are not used for advertising.",
  "shared.pages_cookies.cookie_notice": "Cookie notice",
  "shared.pages_cookies.chlat_work_shows_a_small_informational_cookie_notice_with": "ChlatWork shows a small informational cookie notice with links to this Cookie Policy and the Privacy Policy. Closing the notice stores the chlatwork_cookie_notice_closed flag in localStorage so the notice does not keep appearing.",
  "shared.pages_cookies.the_notice_is_informational_only_and_does_not_include": "The notice is informational only and does not include cookie preference controls.",
  "shared.pages_cookies.analytics": "Analytics",
  "shared.pages_cookies.chlat_work_uses_vercel_web_analytics_to_understand_site": "ChlatWork uses Vercel Web Analytics to understand site usage and improve reliability. Vercel Web Analytics is designed to store anonymized data and does not use cookies.",
  "shared.pages_cookies.chlat_work_also_installs_the_google_tag_with_consent": "ChlatWork also installs the Google tag with Consent Mode. Analytics and advertising storage are denied by default. The tag can receive a consent-state signal without writing analytics or advertising cookies; storage is enabled only after an integrated consent platform sends an appropriate update.",
  "shared.pages_cookies.advertising_cookies": "Advertising cookies",
  "shared.pages_cookies.chlat_work_may_use_third_party_advertising_partners_these": "ChlatWork may use third-party advertising partners. These vendors may use cookies, web beacons, IP addresses, or other identifiers to serve ads, measure ad performance, limit repeated ads, prevent fraud, and show personalized or non-personalized ads.",
  "shared.pages_cookies.managing_cookies": "Managing cookies",
  "shared.pages_cookies.you_can_block_delete_or_limit_cookies_in_your": "You can block, delete, or limit cookies in your browser settings.",
