  "shared.pages_editorial_policy.editorial_policy": "Editorial Policy",
  "shared.pages_editorial_policy.this_page_explains_how_chlat_work_creates_and_maintains": "This page explains how ChlatWork creates and maintains tool guides, educational examples, policy pages, and practical workflow content.",
  "shared.pages_editorial_policy.last_updated_june_29_2026": "Last updated: June 29, 2026",
  "shared.pages_editorial_policy.purpose_of_content": "Purpose of content",
  "shared.pages_editorial_policy.chlat_work_content_is_designed_to_help_users_complete": "ChlatWork content is designed to help users complete practical tasks with less confusion. Pages are written for clarity and speed: what the tool does, when to use it, how to avoid mistakes, and what to verify before using outputs in real workflows.",
  "shared.pages_editorial_policy.how_content_is_created": "How content is created",
  "shared.pages_editorial_policy.each_guide_starts_from_real_tool_behavior_and_user": "Each guide starts from real tool behavior and user workflow needs.",
  "shared.pages_editorial_policy.explanations_are_written_in_plain_language_with_practical_examples": "Explanations are written in plain language with practical examples for Cambodia and Khmer-English usage where relevant.",
  "shared.pages_editorial_policy.technical_and_financial_examples_are_checked_against_current_tool": "Technical and financial examples are checked against current tool logic before publishing.",
  "shared.pages_editorial_policy.pages_are_updated_when_tool_behavior_browser_support_or": "Pages are updated when tool behavior, browser support, or policy requirements change.",
  "shared.pages_editorial_policy.financial_and_ymyl_content_standard": "Financial and YMYL content standard",
  "shared.pages_editorial_policy.pages_related_to_money_expenses_budgeting_and_payback_calculations": "Pages related to money, expenses, budgeting, and payback calculations are treated as higher-risk topics. These pages include stronger limitations, validation reminders, and practical checks.",
  "shared.pages_editorial_policy.financial_tools_are_educational_utilities_not_financial_advice": "Financial tools are educational utilities, not financial advice.",
  "shared.pages_editorial_policy.users_are_reminded_to_verify_assumptions_fees_and_final": "Users are reminded to verify assumptions, fees, and final payment amounts before sending money.",
  "shared.pages_editorial_policy.content_avoids_promises_of_financial_outcomes_or_guaranteed_savings": "Content avoids promises of financial outcomes or guaranteed savings.",
  "shared.pages_editorial_policy.corrections_and_updates": "Corrections and updates",
  "shared.pages_editorial_policy.if_content_is_unclear_outdated_or_incorrect_chlat_work": "If content is unclear, outdated, or incorrect, ChlatWork updates the page and improves examples to prevent repeated confusion.",
